import{_ as a,o as r,c as t,a3 as n}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Related Links","description":"","frontmatter":{"translationSource":{"title":"友情链接","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=cuRlnn75Kga51BX2KAlOuD","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/related-links"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/related-links"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/related-links"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/related-links"}]]},"headers":[],"relativePath":"related-links.md","filePath":"logistics/src/page-cuRlnn75Kga51BX2KAlOuD.md"}'),i={name:"related-links.md"};function o(l,e,p,s,d,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><h1 id="related-links" tabindex="-1">Related Links <a class="header-anchor" href="#related-links" aria-label="Permalink to &quot;Related Links&quot;">​</a></h1><blockquote><p>Source page ID: <code>cuRlnn75Kga51BX2KAlOuD</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=cuRlnn75Kga51BX2KAlOuD" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Unless specified otherwise, group numbers mean QQ groups. Recommend additions in our QQ group. Visitors may comment and review.</p><p><a href="https://factory.ef.yituliu.cn/aef" target="_blank" rel="noreferrer">Endfield Quantitative Calculator</a> Feedback group: 1071155059</p><p>factory.ef.yituliu.cn/aef</p><p>Graphical production allocation and production/consumption calculation: an essential group tool, though still with many shortcomings.</p><p>(Very useful; saves lots of scratch paper. If only it rounded for me: 1.25 machines often cannot be implemented directly.)</p><p><a href="http://fz.wiki" target="_blank" rel="noreferrer">fz Endfield Wiki</a></p><p>fz.wiki</p><p>Currently the best player-created wiki.</p><p>(Oh! Useful map! No need to pay for items to find treasure chests.)</p><p><a href="https://warfarin.wiki/cn" target="_blank" rel="noreferrer">Warfarin Wiki</a> Discord: <a href="https://discord.gg/RjAN7VXxGX" target="_blank" rel="noreferrer">RjAN7VXxGX</a></p><p>warfarin.wiki/cn</p><p>A wiki that is still updated fairly often these days.</p><p>(Not very mobile-friendly.)</p><p><a href="http://end.fffdan.com" target="_blank" rel="noreferrer">Hongshan Archives</a></p><p>end.fffdan.com</p><p>A special wiki for group members, with examples of using the Tianshi database API. It has recently become somewhat hard to access.</p><p>(Not very mobile-friendly, but it plays music.)</p><p><a href="http://endfield-assets.fffdan.com/scalar/" target="_blank" rel="noreferrer">Tianshi Database</a></p><p>endfield-assets.fffdan.com/scalar/</p><p>Endfield data-table/icon/image API, with an AI skill ready for use anytime. Compared with akedata, it also provides a table of data tables</p><p><a href="http://akedata.wiki" target="_blank" rel="noreferrer">Endfield Database</a></p><p>akedata.wiki</p><p>akewiki, a newer wiki that likewise relies on unpacked game data; its database service is faster than the Tianshi Database&#39;s.</p><p><a href="https://ef.yituliu.cn/" target="_blank" rel="noreferrer">Endfield Yituliu</a> Development group: 696486169</p><p>ef.yituliu.cn</p><p>Store/bundle value calculations, pull-saving calculator, gift lookup, sword-selection martial-trial calculator, and a finished AIC blueprint set per version. Whatever “one map” means, there are plenty of functions.</p><p><a href="https://maaend.com/" target="_blank" rel="noreferrer">MaaEnd</a> User group: 1062010346; development group: 1072587329</p><p>maaend.com</p><p>Completes dailies through scripts; very useful.</p><p><a href="https://end.canmoe.com/zh-CN" target="_blank" rel="noreferrer">CEP Endfield Planner</a> Group: 1045523485</p><p>end.canmoe.com/zh-CN</p><p>Essence, forging, and progression planning, plus operator/weapon/equipment viewing and game-text search. Attractive, spacious interface; some content may be missing compared with other wikis.</p><p><a href="http://zipliner.org" target="_blank" rel="noreferrer">Zipliner</a></p><p>zipliner.org</p><p>A zipline map site: simple and clear.</p><p><a href="https://zmdjj.pythonanywhere.com/" target="_blank" rel="noreferrer">Reading Site Made by a Group Member</a></p><p>zmdjj.pythonanywhere.com</p><p>Unnamed for now. It prevents Tencent Docs glitches and links redirecting incorrectly. Continuously updated; it may become an extension of the task board or even replace it.</p><p><a href="https://kokobird28144.github.io/endfield-skydoc/" target="_blank" rel="noreferrer">Task Board Mirror: Endfield-Skydoc</a></p><p>kokobird28144.github.io/endfield-skydoc</p><p>Currently maintained by kokobird, who periodically crawls the main documents, translates them into English (the main purpose), and updates the mirror</p><p><a href="https://dige.aunly.cn/?lang=zh" target="_blank" rel="noreferrer">D.I.G.E</a> Group: 1084531249</p><p>dige.aunly.cn/?lang=zh</p><p>Power-splitting simulation solver: still oscillating generation, now with simulation to prevent outages.</p><p><a href="https://mikunyaaa.github.io/endfield-calculator/" target="_blank" rel="noreferrer">Power-Splitting Calculator</a></p><p>mikunyaaa.github.io/endfield-calculator</p><p>Power-splitting simulation solver, compact and streamlined.</p><p><a href="http://wiki.skland.com" target="_blank" rel="noreferrer">SKLAND</a></p><p>wiki.skland.com</p><p>Hypergryph&#39;s official community: a poor wiki, live-position map, operator progression statistics, etc. Sometimes updates early; official announcements are always accessible.</p><p><a href="https://www.end-axis.com/timeline" target="_blank" rel="noreferrer">Endfield Timeline Planner—Timeline Terminal</a> Discussion group: 1125518981</p><p>www.end-axis.com/timeline</p><p>Combat timeline planner. Group members indifferent to combat rarely need it (redstone players cannot beat the bug.gif). Also team recommendations (timeline plaza).</p><p><a href="http://ef.exgamer.top" target="_blank" rel="noreferrer">Super Player</a></p><p>ef.exgamer.top</p><p>A small tool from Bilibili creator 半壁_Yakoo. Its most distinctive feature at present is the Yuanyuan Manor kitchen-planning assistant.</p><p><a href="http://rahoo.online/" target="_blank" rel="noreferrer">Cover Generator</a></p><p>rahoo.online</p><p>A toolkit from Bilibili creator 拉乎, offering various quick asset-generation options, including common team-introduction covers.</p><p><a href="http://ignoredone.space" target="_blank" rel="noreferrer">ignoredone&#39;s space</a></p><p>ignoredone.space</p><p>A personal-style website from Bilibili creator ignoredone, an expert in Arknights-style design. It offers works, assets, and a path for learning to build projects.</p><p><a href="https://beta.enka.network/endfield/aic/" target="_blank" rel="noreferrer">EnKAD Endfield AIC Simulator</a> Discord: <a href="https://discord.gg/gvXnJhBvWG" target="_blank" rel="noreferrer">gvXnJhBvWG</a> MCP repository: <a href="https://github.com/EugW/enkad_mcp/tree/main" target="_blank" rel="noreferrer">enkad_mcp</a></p><p>beta.enka.network/endfield/aic</p><p>An AIC simulator that produces results quickly and can partly simulate output priority. Currently the simulator closest to actual behavior.</p><p><a href="https://endfield.amiyabot.com/" target="_blank" rel="noreferrer">Endfield Industrial System Simulator</a></p><p>endfield.amiyabot.com</p><p>Also called the amiyabot simulator, though its repository is IndustrialPlanner. It has a cleaner interface, manually configurable priority, and can be edited while running. Results are slower and resource consumption higher; complex limiters are likewise unsupported. It has an automatic layout feature.</p><p><a href="http://opendfieldmap.cn" target="_blank" rel="noreferrer">Endfield Atlas</a> Discussion group: 1075906513; Discord: <a href="https://discord.gg/BFMAKZSUG7" target="_blank" rel="noreferrer">BFMAKZSUG7</a></p><p>opendfieldmap.cn</p><p>A detailed map; tools such as maa can check uncollected archives. Somewhat resource-intensive.</p><p><a href="https://endfieldtools.dev/" target="_blank" rel="noreferrer">Arknights Endfield Tools &amp; Database</a></p><p>?</p><p><a href="http://endfield.wiki.gg" target="_blank" rel="noreferrer">Endfield Talos Wiki</a></p><p>?</p><blockquote><p>Translation note: “Tianshi” and “sword-selection martial trial” are provisional renderings of unpaired names. The Tianshi Database entry stops mid-sentence in the source, ending at “a table of data tables”; the translators have not supplied the missing remainder.</p></blockquote></div>',1)])])}const u=a(i,[["render",o]]);export{h as __pageData,u as default};
